#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_1TO1_NAT FW_NAT; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_PORT fws_tcp_80_443 && fail 'a port group named fws_tcp_80_443 exists; nothing was written'
named FW_GROUP_IP fws_VLAN_10_ && fail 'an IP group named fws_VLAN_10_ exists; nothing was written'
named FW_GROUP_IP fws_historian_dst && fail 'an IP group named fws_historian_dst exists; nothing was written'
named FW_GROUP_IP fws_plcs && fail 'an IP group named fws_plcs exists; nothing was written'
named FW_GROUP_IP fws_fqdn_updates.example.com && fail 'an IP group named fws_fqdn_updates.example.com exists; nothing was written'
named FW_GROUP_IP fws_VLAN_20_ && fail 'an IP group named fws_VLAN_20_ exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_VLAN_10_ --set .COMMENT 'FWShift: VLAN(10)'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.10.0/24
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_historian_dst --set .COMMENT 'FWShift: VLAN(30), 172.16.40.0/24'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.30.0/24
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 172.16.40.0/24
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_plcs --set .COMMENT 'FWShift: plcs'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 172.16.40.11-172.16.40.12
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_fqdn_updates.example.com --set .COMMENT 'FWShift: fqdn updates.example.com'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP updates.example.com
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_VLAN_20_ --set .COMMENT 'FWShift: VLAN(20)'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.20.0/24
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_tcp_80_443 --set .COMMENT 'FWShift: tcp/80,443'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))

# FW_1TO1_NAT
N=$(rows FW_1TO1_NAT)
gc --silent --goto FW_1TO1_NAT --add-row --set .LOCAL_NET 10.10.20.25 --set .REMOTE_NET 203.0.113.25 --set .MASK 32 --set .ENABLE_ARP yes --set .COMMENT 'NAT mail'
N=$((N+1))

# FW_NAT
N=$(rows FW_NAT)
gc --goto FW_NAT --add-row --set .EXT_IF ext1 --set .IN_IP 0.0.0.0/0 --set .COMMENT 'NAT to the uplink'
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
